from math import gcd
from functools import reduce

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    marker_cells = [
        (r, c) for r in range(h) for c in range(w)
        if grid[r][c] not in (0, 8)
    ]
    shape_cells = [
        (r, c) for r in range(h) for c in range(w) if grid[r][c] == 8
    ]
    if not marker_cells or not shape_cells:
        return out

    # The repeated square-unit size is the gcd of contiguous 8-run lengths.
    runs = []
    for line in (grid, list(map(list, zip(*grid)))):
        for row in line:
            n = 0
            for value in row:
                if value == 8:
                    n += 1
                elif n:
                    runs.append(n)
                    n = 0
            if n:
                runs.append(n)
    size = reduce(gcd, runs)

    sr0 = min(r for r, c in shape_cells)
    sc0 = min(c for r, c in shape_cells)
    mr0 = min(r for r, c in marker_cells)
    mc0 = min(c for r, c in marker_cells)
    mr1 = max(r for r, c in marker_cells)
    mc1 = max(c for r, c in marker_cells)

    pattern = [
        [grid[r][c] for c in range(mc0, mc1 + 1)]
        for r in range(mr0, mr1 + 1)
    ]
    # Rotate the small color pattern 90 degrees clockwise.
    pattern = [list(row) for row in zip(*pattern[::-1])]

    for r, c in shape_cells:
        br, bc = (r - sr0) // size, (c - sc0) // size
        if br < len(pattern) and bc < len(pattern[0]):
            color = pattern[br][bc]
            if color:
                out[r][c] = color

    return out
